	public class EarthBossReadyState : BossReadyState
	{
		private Vector2 currentPosition;

		private int maxCubeCount = 6;

		private EarthBossCube[] earthBossCubes;

		public new EarthBoss parent;

		public EarthBossReadyState(string newName, FSM newFSM, EarthBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			earthBossCubes = new EarthBossCube[maxCubeCount];
			idleNormalizedTime = 0.8f;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			exitTime = StdExitTime * 2f;
			float num = exitTime * 0.25f;
			exitTime -= num;
			windupStopwatchID = ChaosStopwatch.Begin(num);
		}

		public override void PlayFlair()
		{
			base.PlayFlair();
			currentPosition = parent.transform.position;
			for (int i = 0; i < maxCubeCount; i++)
			{
				earthBossCubes[i] = Globals.ChaosInst<EarthBossCube>(EarthBossCube.Prefab, parent.bossObjects, currentPosition + Globals.GetCirclePositionVector(maxCubeCount, i) * 1.5f);
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, earthBossCubes[i].transform.position);
			}
			SoundManager.PlayAudioWithDistance("RockForm", currentPosition);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, currentPosition);
			string audioID = "GroundSlam";
			Vector2? soundOrigin = currentPosition;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}

		public override void PlayEndFlair()
		{
			base.PlayEndFlair();
			for (int i = 0; i < maxCubeCount; i++)
			{
				earthBossCubes[i].anim.speed = 2f;
			}
		}

		public override void OnExit()
		{
			for (int i = 0; i < maxCubeCount; i++)
			{
				if (earthBossCubes[i] != null)
				{
					earthBossCubes[i].Burst();
				}
			}
		}
	}

