	public class EarthBossPoisonBombState : BossSkillState
	{
		private PoisonBomb currentPB;

		private Vector2 targetLocation;

		private float spawnRange = 3f;

		private int maxSpawnCount = 6;

		private float spawnDelay = 0.05f;

		private int spawnStopwatchID;

		private int spawnIndex;

		private float bombPoisonDuration = 3f;

		private float bombAttackRadius = 1.5f;

		private float bombSpacing = 3f;

		private bool targetLocked;

		public new EarthBoss parent;

		public EarthBossPoisonBombState(string newName, FSM newFSM, EarthBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("Clap", -1, 0f);
			parent.PlayEarthLoop(status: true);
			windupTime = StdWindupTime * 0.75f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 2f;
			spawnStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, spawnDelay, maxSpawnCount);
			spawnIndex = UnityEngine.Random.Range(0, maxSpawnCount);
			targetLocked = false;
		}

		public override void ExecuteSkill()
		{
			if (!targetLocked)
			{
				targetLocked = true;
				if (parent.UpdateTargetInfo() == null)
				{
					ExitTransition();
					return;
				}
				targetLocation = parent.closestTargetInfo.transform.position;
			}
			switch (ChaosStopwatch.CheckInterval(spawnStopwatchID))
			{
			case StopwatchState.Ready:
				parent.anim.Play("Clap", -1, 0.75f);
				ThrowBomb(targetLocation + spawnRange * Globals.GetCirclePositionVector(maxSpawnCount, spawnIndex));
				spawnIndex++;
				SoundManager.PlayAudioWithDistance("StandardThrow", parent.transform.position);
				break;
			case StopwatchState.Done:
				parent.PlayEarthLoop(status: false);
				base.ExecuteSkill();
				break;
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.PlayEarthLoop(status: false);
		}

		private void ThrowBomb(Vector2 givenPosition)
		{
			if (Globals.CheckCircle(givenPosition, 0.25f, ChaosCollisions.layerPit))
			{
				currentPB = ChaosInst<PoisonBomb>(PoisonBomb.Prefab, parent.attackOriginTrans.position);
				currentPB.attackBox.SetAttackInfo(parent.skillCategory, skillID);
				currentPB.targetPosition = givenPosition;
				currentPB.randomOffset = 0f;
				currentPB.rotationCount = 1f;
				currentPB.explosionDelay = windupTime;
				currentPB.poisonDuration = bombPoisonDuration;
				currentPB.attackRadius = bombAttackRadius;
				currentPB.poisonType = PoisonType.Purple;
			}
		}
	}

