public class EarthBossRockThrowState : BossSkillState
{
	private int maxSpawnCount = 3;
	protected int currentSpawnCount;
	private float spawnRange = 1.5f;
	protected Boulder currentRT;
	private Vector2 currentPosition;
	private Vector2 spawnPosition;
	private Vector2 readyPosition;
	private Vector2 riseVector;
	private float punchDelay;
	private int punchStopwatchID;
	private bool forehandAnim;
	private string animName;
	protected string animOption0;
	protected string animOption1;
	protected float animActiveTime;
	private bool rockCreated;
	private bool rockThrown;
	private float rockSpeed;
	public EarthBossRockThrowState(string newName, FSM newFSM, Boss newEnt)
		: base(newName, newFSM, newEnt)
	{
		riseVector = parent.attackOriginTrans.localPosition;
		animOption0 = "Hook";
		animOption1 = "Hook2";
		animActiveTime = 0.33f;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		windupTime = StdWindupTime;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		punchDelay = windupTime * 0.5f;
		rockSpeed = Mathf.Lerp(32f, 40f, currentDiffValue);
		rockCreated = false;
		currentSpawnCount = 0;
		PlayAnim();
		HandleRockSpawnMove();
	}
	public override void WindupUpdate()
	{
		HandleRockSpawnMove();
	}
	public override void ExecuteSkill()
	{
		if (!rockThrown)
		{
			rockThrown = true;
			PlayAnim(switchAnim: true);
			ThrowRock();
			punchStopwatchID = ChaosStopwatch.Begin(punchDelay);
		}
		if (currentSpawnCount >= maxSpawnCount)
		{
			base.ExecuteSkill();
		}
		else if (ChaosStopwatch.Check(punchStopwatchID))
		{
			rockCreated = false;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime * 0.5f);
			HandleRockSpawnMove();
		}
	}
	public virtual void PlayAnim(bool switchAnim = false)
	{
		animName = ((!forehandAnim) ? animOption0 : animOption1) + parent.facingDirection;
		if (!ChaosStopwatch.Check(windupStopwatchID))
		{
			parent.anim.PlayDirectional(animName);
			return;
		}
		parent.anim.PlayDirectional(animName, -1, animActiveTime);
		if (switchAnim)
		{
			forehandAnim = !forehandAnim;
		}
	}
	private void HandleRockSpawnMove()
	{
		if (!rockCreated)
		{
			rockCreated = true;
			rockThrown = false;
			currentSpawnCount++;
			CreateRock();
		}
		if (!(currentRT == null))
		{
			currentRT.rigidbody2D.MovePosition(Vector2.Lerp(spawnPosition, readyPosition, ChaosStopwatch.GetTimePercentage(windupStopwatchID)));
			if (currentSpawnCount == 1)
			{
				PlayAnim();
			}
		}
	}
	private void CreateRock()
	{
		UpdateTargetVector(updateInfo: true);
		currentPosition = parent.transform.position;
		parent.FaceTarget(currentPosition + targetVector, parent.animFacingDirections);
		spawnPosition = currentPosition + targetVector * spawnRange;
		readyPosition = spawnPosition + riseVector;
		currentRT = ChaosInst<Boulder>(Boulder.Prefab, spawnPosition);
		currentRT.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentRT.attackBox.knockbackOverwriteVector = targetVector;
		currentRT.attackBox.gameObject.SetActive(value: false);
		currentRT.moveSpeed = rockSpeed;
		currentRT.rotationsPerSecond = 0f;
		currentRT.SetMode(BoulderType.Cube);
		PoolManager.GetPoolItem<DustEmitter>().EmitCircle(40, 0.5f, -1f, -1f, spawnPosition);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, spawnPosition);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, spawnPosition, RockDebrisEmitter.SmallCircleExplosionOverride);
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, spawnPosition, RockMedDebrisEmitter.SmallCircleExplosionOverride);
		SoundManager.PlayAudioWithDistance("EarthCrumble", currentPosition);
		CameraController.ShakeCamera();
	}
	private void ThrowRock()
	{
		if (!(currentRT == null))
		{
			currentRT.pointTowardMoveVector = true;
			currentRT.moveVector = targetVector;
			currentRT.attackBox.gameObject.SetActive(value: true);
			switch (parent.facingDirection)
			{
			case FacingDirection.Right:
				currentRT.SetMode(BoulderType.FistRight);
				break;
			case FacingDirection.Left:
				currentRT.SetMode(BoulderType.FistLeft);
				break;
			case FacingDirection.Up:
				currentRT.SetMode(BoulderType.FistUp);
				break;
			case FacingDirection.Down:
				currentRT.SetMode(BoulderType.FistDown);
				break;
			}
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(5, currentRT.transform.position, RockDebrisEmitter.SmallCircleFastExplosionOverride);
			PoolManager.GetPoolItem<DashAirBurst>().Burst(readyPosition, targetVector, useOffset: false);
			string audioID = "RockPunchImpact";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = UnityEngine.Random.Range(0.5f, 0.6f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			SoundManager.PlayAudioWithDistance("RockForm", parent.transform.position);
			CameraController.ShakeCamera();
		}
	}
}
