		{
			parent = newEnt;
			useTargetHurtBox = false;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("PBAoE", -1, 0f);
			windupTime = StdWindupTime;
			summonStopwatch.SetDelay(windupTime);
			punchStopwatch.SetDelay(windupTime);
			exitStopwatch.SetDelay(StdExitTime);
			wallList.Clear();
			summonStopwatch.IsRunning = true;
			punched = false;
			summoned = false;
			SummonWall();
		}
		public override void Update()
		{
			if (!punched)
			{
				if (!summoned)
				{
					if (!summonStopwatch.IsRunning)
					{
						summoned = true;
						parent.anim.Play("PBAoE", -1, 1f);
						CameraController.ShakeCamera();
						punchStopwatch.IsRunning = true;
					}
					return;
				}
				if (punchStopwatch.IsRunning)
				{
					if (punchStopwatch.TimePercentage > 0.5f)
					{
						parent.anim.PlayDirectional("Punch" + parent.facingDirection);
					}
					return;
				}
				punched = true;
				parent.anim.PlayDirectional("Punch" + parent.facingDirection, -1, 0.33f);
				SoundManager.PlayAudioWithDistance("GroundSlam", parent.transform.position);
				foreach (KnockbackWall wall in wallList)
				{
					if (!(wall == null))
					{
						wall.WallStruck(targetVector, parent.skillCategory, wallDamage, wallForce);
					}
				}
				exitStopwatch.IsRunning = true;
			}
			if (!exitStopwatch.IsRunning)
			{
				ExitTransition();
			}
		}
		public void SummonWall()
		{
			directionalVector = new Vector2(0f - targetVector.y, targetVector.x);
			wallVector = targetVector * spawnDistance - Mathf.FloorToInt((float)wallCount * 0.5f) * directionalVector + (Vector2)parent.transform.position;
			for (int i = 0; i < wallCount; i++)
			{
				KnockbackWall knockbackWall = ChaosInst<KnockbackWall>(KnockbackWall.Prefab, wallVector);
				knockbackWall.attack.SetAttackInfo(parent.skillCategory, KnockbackWall.skillID);
				knockbackWall.castTime = summonStopwatch.Delay;
				knockbackWall.lifeTime = 1.5f;
				knockbackWall.rootTime = 2f;
				knockbackWall.IgnoreWallToWallCollisions = true;
				knockbackWall.spawnExplosionOnDestroy = true;
				knockbackWall.destroyOnImpact = false;
				knockbackWall.IsRooted = true;
				wallList.Add(knockbackWall);
				wallVector += directionalVector;
			}
		}
	}
