	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteTrans = transform.Find("Sprite");
		spritePosition = spriteTrans.position;
		startHeight = transform.position.y;
		spinning = false;
	}
	private void Start()
	{
		endHeight = startHeight + Random.Range(endHeightMin, endHeightMax);
		riseTime = Random.Range(riseTimeMin, riseTimeMax);
		riseTimer = new ChaosQuickStopwatch(riseTime);
		dropDelay = riseTime + dropDelay;
		dropTimer = new ChaosQuickStopwatch(dropDelay);
		RiseUp();
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, spritePosition);
		FloorCrackEffect poolItem = PoolManager.GetPoolItem<FloorCrackEffect>();
		Vector3 position = spriteTrans.transform.position;
		float animDuration = 0f;
		FloorCrackEffectType effectType = ((!useSmallCrack) ? FloorCrackEffectType.Medium : FloorCrackEffectType.Small);
		poolItem.Crack(position, animDuration, 0.75f, 0.5f, effectType);
	}
	private void Update()
	{
		if (autoDrop && delayStarted)
		{
			if (!dropStarted)
			{
				if (!dropTimer.IsRunning)
				{
					dropTimer.SetDelay(dropTime);
					dropTimer.IsRunning = true;
					dropStarted = true;
				}
			}
			else if (dropTimer.IsRunning)
			{
				if (spriteTrans != null)
				{
					spritePosition.y = Mathf.Lerp(endHeight, startHeight, dropTimer.TimePercentage);
					spriteTrans.position = spritePosition;
				}
			}
			else
			{
				Burst();
			}
		}
		else if (!riseTimer.IsRunning)
		{
			if (autoDrop && !delayStarted)
			{
				dropTimer.IsRunning = true;
				delayStarted = true;
			}
		}
		else
		{
			if (!spinning && riseTimer.TimePercentage >= 0.33f)
			{
				anim.Play("Spin", -1, 0f);
				anim.speed = Random.Range(0.5f, 1.5f);
				spinning = true;
			}
			if (spriteTrans != null)
			{
				spritePosition.y = Mathf.Lerp(startHeight, endHeight, riseTimer.TimePercentage);
				spriteTrans.position = spritePosition;
			}
		}
	}
	private void RiseUp()
	{
		riseTimer.IsRunning = true;
	}
	public void Burst()
	{
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(5, spritePosition, RockDebrisEmitter.SmallCircleFastExplosionOverride);
		SoundManager.PlayAudioWithDistance("RockExplode", spritePosition);
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
	}
