					{
						return;
					}
					if (!parent.anim.AnimPlayed(8f))
					{
						if (superChargeSFX != null && !superChargeSFX.isPlaying)
						{
							superChargeSFX = SoundManager.PlayAudio("ChaosBeamLoop");
						}
						if (!powerDownSFXPlayed && parent.anim.AnimPlayed(6.5f))
						{
							powerDownSFXPlayed = true;
							SoundManager.PlayAudio("ChaosWarble", 1f, ignoreTimeRestriction: false, 0.2f);
