	public class FinalBossLightningBossState : BossSkillState
	{
		private int pointCount = 5;
		private int pointOffset = 3;
		private float pointRange = 5f;
		private int randomSeed;
		private int randomMultiplier = 5;
		private List<ShockNetOrb> snList = new List<ShockNetOrb>();
		private Vector2 targetLocation;
		private Vector2 nextPosition;
		public new FinalBoss parent;
		public override float StdWindupTime => parent.SpellStartTime;
		public override float StdExitTime => parent.SpellExitTime;
		public FinalBossLightningBossState(string newName, FSM newFSM, FinalBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			snList.Clear();
			if (parent.closestTargetInfo == null)
			{
				ExitTransition();
				return;
			}
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.5f);
			exitTime = StdExitTime * 1.5f;
			randomSeed = UnityEngine.Random.Range(0, pointCount);
			targetLocation = parent.closestTargetInfo.position + Vector3.up;
			string audioID = "StandardThrow";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			for (int i = 0; i < pointCount; i++)
			{
				CreateShockNetOrb(GetCalculatedPosition(i) + Vector2.down);
				snList[i].targetLocList.Add(GetCalculatedPosition((i + 1) % pointCount));
				snList[i].targetLocList.Add(GetCalculatedPosition((i + pointOffset) % pointCount));
				snList[i].targetLocList.Add(targetLocation);
			}
			parent.FaceTarget(targetLocation, parent.animFacingDirections);
			parent.anim.PlayDirectional("Backhand" + parent.facingDirection, -1, 0.25f);
		}
		private void CreateShockNetOrb(Vector2 givenPosition)
		{
			ShockNetOrb shockNetOrb = ChaosInst<ShockNetOrb>(ShockNetOrb.Prefab, parent.transform.position);
			shockNetOrb.SetSkillVars(parent.skillCategory, skillID);
			shockNetOrb.targetPosition = givenPosition;
			shockNetOrb.initDelay = 0.25f;
			shockNetOrb.attackDelay = 0.25f;
			snList.Add(shockNetOrb);
		}
		private Vector2 GetCalculatedPosition(int givenPosition)
		{
			return targetLocation + pointRange * Globals.GetCirclePositionVector(pointCount * randomMultiplier, givenPosition * randomMultiplier + randomSeed);
		}
	}
