	public override TargetInfo UpdateTargetInfo(float rangeOverride = -1f, bool reqLOS = false)
	{
		if (!fsm.currentStateName.Contains("FinalBossChaos") && fsm.currentStateName != "FireBossDragonLine" && fsm.currentStateName != "EarthBossRockThrow")
		{
			closestTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, (!(rangeOverride > 0f)) ? CurrentAlertRadius : rangeOverride, onlyTargetPlayers, null, gameObject, reqLOS, reqLOS ? lineOfSightLayerMask : 0);
			return closestTargetInfo;
		}
		return base.UpdateTargetInfo(rangeOverride, reqLOS);
	}
	public override void TransitionToNextState()
	{
		if (chaosMode)
		{
			if (fsm.currentStateName == chaosShieldState.name || fsm.currentStateName == idleShieldState.name)
			{
				chaosIndex = (chaosIndex + UnityEngine.Random.Range(1, chaosCount)) % chaosCount;
				fsm.ChangeState(chaosPatternList[chaosIndex].name, allowSelfTransition: true);
			}
			else
			{
				fsm.ChangeState(idleShieldState.name);
			}
			return;
		}
		if (UpdateTargetInfo() == null)
		{
			fsm.ChangeState(fsm.defaultStateName);
			return;
		}
		nextAttackIndex = attackIndex + 1;
		if (nextAttackIndex < 0 || nextAttackIndex >= attackIndexCurrentMax)
		{
			if (superMode)
			{
				bossUltimateState = superEraserState;
				if (!bossUltimateState.UltIsReady)
				{
					chaosFinisherUsed = true;
				}
			}
			if (chaosFinisherUsed)
			{
				chaosFinisherUsed = false;
				standardPatternList.Shuffle();
				superPatternList.Shuffle();
				AllowHurtState(status: true);
				nextSkillRange = -1f;
				if (bossTargetList != null && bossTargetList.Count == 0)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
				else
				{
					fsm.ChangeState(bossDashState.name, allowSelfTransition: true);
				}
			}
			else
			{
				chaosFinisherUsed = true;
				if (!superMode)
				{
					chaosIndex = (chaosIndex + UnityEngine.Random.Range(1, chaosCount)) % chaosCount;
					bossUltimateState = chaosPatternList[chaosIndex];
				}
				bossUltimateState.queueUltimate = true;
				fsm.ChangeState(bossUltimateState.name, allowSelfTransition: true);
			}
			return;
		}
		AllowHurtState(status: false);
		if (superMode)
		{
			nextAttackName = superPatternList[nextAttackIndex].name;
		}
		else
		{
			nextAttackName = standardPatternList[nextAttackIndex].name;
			if (nextAttackIndex == attackIndexCurrentMax - 1)
			{
				nextAttackName = bossSkillDict[nextAttackName];
			}
		}
		nextSkillRange = ((!skillRangeDict.ContainsKey(nextAttackName)) ? 8f : skillRangeDict[nextAttackName]);
		if (fsm.currentStateName != bossDashState.name)
		{
			fsm.ChangeState(bossDashState.name, allowSelfTransition: true);
			return;
		}
		attackIndex++;
		fsm.ChangeState(nextAttackName, allowSelfTransition: true);
		if (!superMode)
		{
			EmitElement(skillEleDict[nextAttackName]);
		}
	}
	public override void AllowHurtState(bool status)
	{
		base.AllowHurtState(status);
		evadeMode = status;
		if (status)
		{
			if (superMode)
			{
				evadeStopwatch.SetDelay(Mathf.Max(0.25f, Mathf.Lerp(0.5f, 1f, health.HealthPercentage) * SkillState.CooldownMultiStat.CurrentValue), stopCurrent: true, autoStart: true);
			}
			else
			{
				evadeStopwatch.SetDelay(Mathf.Max(0.25f, Mathf.Lerp(1.4f, 2f, health.HealthPercentage) * SkillState.CooldownMultiStat.CurrentValue), stopCurrent: true, autoStart: true);
			}
		}
		else
		{
			evadeStopwatch.IsRunning = false;
		}
		if (status && !chaosMode && !fsm.currentStateName.Contains("Dead"))
		{
			PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, transform.position);
			SetOutlineColor(Color.clear, Color.clear);
		}
	}
	protected Vector2 GetTrackingVector(float trackVal = 3f)
	{
		UpdateTargetInfo();
		if (closestTargetInfo == null || closestTargetInfo.hurtBoxTransform == null || closestTargetInfo.entity == null)
		{
			return Vector2.zero;
		}
		return (closestTargetInfo.hurtBoxPosition + (Vector3)closestTargetInfo.entity.rigidbody2D.velocity.normalized * Mathf.Min(trackVal, Mathf.Abs(closestTargetInfo.distance - 1f) / Mathf.Max(trackVal, 1f)) - attackOriginTrans.position).normalized;
	}
	public void ToggleShieldHurtBox(bool enable = true)
	{
		if (enable)
		{
			normalHurtBoxCollider.enabled = false;
			shieldHurtBoxCollider.enabled = true;
			hurtBoxCollider = shieldHurtBoxCollider;
			normalFloorContactCollider.enabled = false;
			shieldFloorContactCollider.enabled = true;
		}
		else
		{
			normalHurtBoxCollider.enabled = true;
			shieldHurtBoxCollider.enabled = false;
			hurtBoxCollider = normalHurtBoxCollider;
			normalFloorContactCollider.enabled = true;
			shieldFloorContactCollider.enabled = false;
		}
	}
	private void InitAttackPatterns()
	{
		standardPatternList = new List<BossSkillState> { fireAtkState, airAtkState, earthAtkState, lightningAtkState, waterAtkState };
		standardPatternList.Shuffle();
		chaosPatternList = new List<BossUltimateState> { chaosGrabState, chaosBallState, chaosWaveState, chaosBeamState, chaosSummonState };
		chaosCount = chaosPatternList.Count;
		chaosIndex = UnityEngine.Random.Range(0, chaosCount);
		superPatternList = new List<BossSkillState> { superScytheState, superLungeState, superCoilState, superBeamState, superSpearState, superClusterState };
	}
	private void EmitElement(ElementType givenElement)
	{
		StartCoroutine(EmitElementParticles(givenElement));
	}
	private IEnumerator EmitElementParticles(ElementType givenElement)
	{
		elementEmitter.startColor = eleColorDict[givenElement];
		elementEmitter.Emit(50);
		elementEmitter.Play();
		yield return waitForEmitDelay;
		elementEmitter.Stop();
	}
}

public class FinalBossSuperScytheState : BossSkillState
{
	private ChaosScytheObject currentCS;
	public new FinalBoss parent;
	public override float StdWindupTime => parent.SpellStartTime;
	public override float StdExitTime => parent.SpellExitTime;
	public FinalBossSuperScytheState(string newName, FSM newFSM, FinalBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		disablePowerUpEffect = true;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		windupTime = StdWindupTime;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		comboCount = 0;
		animName = "Forehand";
		parent.anim.PlayDirectional(animName + parent.facingDirection);
	}
	public override void WindupUpdate()
	{
		base.WindupUpdate();
		if (ChaosStopwatch.GetTimePercentage(windupStopwatchID) > 0.25f)
		{
			parent.anim.PlayDirectional(animName + parent.facingDirection);
		}
	}
	public override void FixedUpdate()
	{
		if (currentCS != null)
		{
			currentCS.transform.position = parent.attackOriginTrans.position;
		}
	}
	public override void ExecuteSkill()
	{
		parent.movement.moveVector = targetVector;
		parent.movement.MoveToMoveVector(25f);
		CameraController.ShakeCamera(0.3f);
		comboCount++;
		finalHit = comboCount >= maxComboCount;
		parent.anim.PlayDirectional(animName + parent.facingDirection, -1, 0.5f);
		animName = ((!(animName == "Forehand")) ? "Forehand" : "Backhand");
		if (!finalHit)
		{
			CreateScytheSlash();
		}
		if (finalHit)
		{
			currentCS.anim.Play("SwingLarge", -1, 0f);
			currentCS.attack.ChangeAttackInfoLevel(3);
			base.ExecuteSkill();
			return;
		}
		windupStopwatchID = ChaosStopwatch.Begin(comboInterval);
		if (comboCount > 1)
		{
			currentCS.anim.Play("SpinFront", -1, 0f);
			currentCS.useAnimTime = false;
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		ResetScythe();
	}
	private void CreateScytheSlash()
	{
		ResetScythe();
		currentCS = ChaosInst<ChaosScytheObject>(ChaosScytheObject.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(targetVector), parent.attackOriginTrans);
		currentCS.attack.SetAttackInfo(parent.skillCategory, skillID, comboCount);
		currentCS.attack.knockbackOverwriteVector = targetVector;
		currentCS.attackVec = targetVector;
		currentCS.negateScript.enabled = true;
		currentCS.negateScript.skillCategory = parent.skillCategory;
	}
	private void ResetScythe()
	{
		if (!(currentCS == null))
		{
			currentCS.transform.SetParent(parent.bossObjects);
			currentCS.useLifeTime = true;
			currentCS.lifeStopwatchID = ChaosStopwatch.Begin(0.5f);
			currentCS.EmitRing();
			currentCS.EndAttack();
			currentCS = null;
		}
	}
}
public class FinalBossSuperLungeState : BossSkillState
{
	private ChaosLunge currentCL;
	private NumVarStatMod dashSpdMod;
	private NumVarStatMod dashDurMod;
	public new FinalBoss parent;
	public override float StdWindupTime => parent.SpellStartTime;
	public override float StdExitTime => parent.SpellExitTime;
	public FinalBossSuperLungeState(string newName, FSM newFSM, FinalBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		disablePowerUpEffect = true;
		dashSpdMod = new NumVarStatMod(newName, 50f, 10, VarStatModType.Override);
		dashDurMod = new NumVarStatMod(newName, 0.15f, 10, VarStatModType.Override);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		isSecondLunge = fsm.previousState == this;
		windupTime = ((!isSecondLunge) ? StdWindupTime : (StdWindupTime * 0.3f));
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 0.75f;
		parent.movement.dashVector = targetVector;
		parent.movement.dashSpeedStat.AddMod(dashSpdMod);
		parent.movement.dashDurationStat.AddMod(dashDurMod);
		parent.movement.dashTimer = dashDurMod.modValue;
		ToggleEnemyFloorCollisions(status: false);
		dashDelayed = false;
		dashCompleted = false;
		lungeCreated = false;
		holdOffset = targetVector * 0.75f;
		ChaoticBurst.CreateBurst(parent.attackOriginTrans.position, string.Empty, string.Empty);
		CameraController.ShakeCamera(0.25f);
		parent.anim.PlayDirectional("Forehand" + parent.facingDirection);
	}
	public override void Update()
	{
		if (!lungeCreated && dashDelayed)
		{
			lungeCreated = true;
			CreateChaosLunge();
		}
		base.Update();
	}
	public override void FixedUpdate()
	{
		if (dashCompleted)
		{
			return;
		}
		if (!dashDelayed)
		{
			if (ChaosStopwatch.Check(windupStopwatchID))
			{
				dashDelayed = true;
			}
		}
		else if (parent.movement.DashToTarget())
		{
			dashCompleted = true;
			parent.movement.EndMovement();
			ToggleEnemyFloorCollisions();
			parent.movement.moveVector = targetVector;
			parent.movement.MoveToMoveVector(8f);
			if (currentCL != null)
			{
				currentCL.rigidbody2D.velocity = targetVector * 8f;
				currentCL.StopMove();
			}
		}
		else if (currentCL != null)
		{
			currentCL.transform.position = parent.attackOriginTrans.position + holdOffset;
		}
	}
	public override void ExecuteSkill()
	{
		if (dashCompleted)
		{
			base.ExecuteSkill();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		ToggleEnemyFloorCollisions();
		parent.movement.dashSpeedStat.RemoveMod(dashSpdMod);
		parent.movement.dashDurationStat.RemoveMod(dashDurMod);
	}
	public override void ExitTransition()
	{
		if (isSecondLunge)
		{
			base.ExitTransition();
		}
		else
		{
			fsm.ChangeState(skillID, allowSelfTransition: true);
		}
	}
	private void CreateChaosLunge()
	{
		currentCL = ChaosInst<ChaosLunge>(ChaosLunge.Prefab, parent.attackOriginTrans.position + holdOffset);
