public class FinalBossExitRoom : MonoBehaviour
{
	public Vector2 exitPortalSpawnOffset;
	public Vector2 exitPortalTargetPosition;
	public Vector2 exitPortalTargetOffset;
	public Vector2 bossSpawnOffset;
	public Vector2 roomColSize;
	public Vector2 roomColOffset;
	public GameObject finalPortalEffects;
	private float spawnRange = 7f;
	private Vector2 currentPosition;
	private SurvivalRoom currentSRoom;
	private List<Enemy.EName> currentEnemyList;
	private List<List<Enemy.EName>> enemyGroupList = new List<List<Enemy.EName>>
	{
		new List<Enemy.EName>
		{
			Enemy.EName.LaserOrb,
			Enemy.EName.LaserOrb,
			Enemy.EName.LaserOrb,
			Enemy.EName.LaserOrb,
			Enemy.EName.LaserOrb
		},
		new List<Enemy.EName>
		{
			Enemy.EName.SuperKnight,
			Enemy.EName.SuperMage,
			Enemy.EName.SuperRogue,
			Enemy.EName.SuperArcher,
			Enemy.EName.SuperLancer,
			Enemy.EName.SuperSummoner
		}
	};
	private void Start()
	{
		currentPosition = transform.position;
		CreateSurvivalRoom(0);
		CreateSurvivalRoom(1, spawnBoss: true);
	}
	private void Update()
	{
		if (currentSRoom != null && currentSRoom.roomCleared)
		{
			CreateTreasureAndExit(currentPosition + exitPortalSpawnOffset);
			enabled = false;
		}
	}
	private void CreateTreasureAndExit(Vector2 givenPosition)
	{
		PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(givenPosition + Vector2.up * 0.5f, string.Empty, 0.125f);
		Portal portal = Globals.ChaosInst<Portal>(Portal.Prefab, transform.parent, givenPosition);
		portal.targetLocation = exitPortalTargetPosition;
		portal.targetSpawnOffset = exitPortalTargetOffset;
		portal.createReturnPortal = true;
		portal.color = new Color(0.4f, 0f, 1f, 1f);
		portal.portalLight.enabled = false;
		portal.portalSprite.enabled = false;
		portal.circlePartSys.gameObject.SetActive(value: false);
		portal.edgePartSys.gameObject.SetActive(value: false);
		finalPortalEffects.SetActive(value: true);
		TreasureChest treasureChest = Globals.ChaosInst<TreasureChest>(TreasureChest.Prefab, transform.parent, currentPosition);
		treasureChest.lootTableName = "TreasureChestMiniBossFinale";
		treasureChest.transform.SetParent(transform);
	}
	private void CreateSurvivalRoom(int givenIndex, bool spawnBoss = false)
	{
		currentSRoom = Globals.ChaosInst<SurvivalRoom>(SurvivalRoom.Prefab, transform, currentPosition);
		currentSRoom.order = givenIndex;
		bool flag = givenIndex != 0;
		BoxCollider2D[] components = currentSRoom.GetComponents<BoxCollider2D>();
		foreach (BoxCollider2D boxCollider2D in components)
		{
			if (flag)
			{
				boxCollider2D.enabled = false;
				continue;
			}
			flag = true;
			boxCollider2D.size = roomColSize;
			boxCollider2D.offset = roomColOffset;
			boxCollider2D.enabled = false;
			boxCollider2D.enabled = true;
		}
		currentEnemyList = enemyGroupList[givenIndex];
		if (spawnBoss)
		{
			CreateEnemyFactory(currentEnemyList[Random.Range(0, currentEnemyList.Count)], currentPosition + bossSpawnOffset, 0.75f, currentSRoom.transform);
			return;
		}
		int count = currentEnemyList.Count;
		for (int j = 0; j < count; j++)
		{
			Vector2 circlePositionVector = Globals.GetCirclePositionVector(count, j);
			CreateEnemyFactory(currentEnemyList[j], Globals.GetLinecastVector(currentPosition, currentPosition + circlePositionVector * spawnRange, ChaosCollisions.layerAll) - circlePositionVector * 1.5f, Random.Range(0.1f, 0.25f), currentSRoom.transform);
		}
	}
	private void CreateEnemyFactory(Enemy.EName givenName, Vector2 givenLoc, float givenTimer, Transform givenTrans)
	{
		EnemyFactory enemyFactory = Globals.ChaosInst<EnemyFactory>(EnemyFactory.Prefab, givenTrans, givenLoc);
		enemyFactory.enemyPrefabKey = givenName.ToString();
		enemyFactory.spawnTimer = givenTimer;
		enemyFactory.maxSpawnCycles = 1;
		enemyFactory.enemiesPerCycle = 1;
		enemyFactory.invalidSpawnArea = Vector2.zero;
		enemyFactory.spawnArea = Vector2.zero;
		enemyFactory.enemiesDropLoot = false;
		enemyFactory.disableCountDeath = true;
	}
}
