using System;
using System.Collections;
using UnityEngine;
public class FinalBossRoomEventHandler : BossRoomEventHandler
{
	public Light stageLight;
	public GameObject lightContainer;
	public GameObject playerSpawnObj;
	public string bossChaosIntroDialogID;
	public string bossSuperIntroDialogID;
	private FinalBoss finalBoss;
	private bool secondFormStarted;
	private bool thirdFormStarted;
	private WaitForSeconds waitForSplitSec = new WaitForSeconds(0.025f);
	private WaitForSeconds waitForLamp = new WaitForSeconds(0.07f);
	private NumVarStatMod devadeMod = new NumVarStatMod("SuperSura", -0.8f, 10, VarStatModType.LateMultiplicative);
	public GameObject[] superModeLamps;
	private bool superModeAvailable;
	public Torch[] regularModeTorches;
	public override void Awake()
	{
		base.Awake();
		if (playerSpawnObj != null)
		{
			playerSpawnObj.SetActive(Level.isBossRushMode);
		}
	}
	public override void Start()
	{
		base.Start();
		boss = GameObject.Find("FinalBoss").GetComponent<FinalBoss>();
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		bool flag = !Level.isBossRushMode && GameDataManager.GameCleared;
		if (flag)
		{
			int num = 0;
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player == null)
				{
					continue;
				}
				foreach (string chaosSkill in LootManager.chaosSkillList)
				{
					if (player.skillsDict.ContainsKey(chaosSkill) && player.skillsDict[chaosSkill].isUnlocked)
					{
						num++;
					}
				}
				break;
			}
			flag = num > 9;
		}
		if (flag)
		{
			for (int j = 0; j < regularModeTorches.Length; j++)
			{
				if (regularModeTorches[j] != null)
				{
					regularModeTorches[j].Break();
				}
			}
			return;
		}
		for (int k = 0; k < superModeLamps.Length; k++)
		{
			if (superModeLamps[k] != null)
			{
				superModeLamps[k].SetActive(value: false);
			}
		}
	}
	public override void Update()
	{
		if (!bossSpawned || exitSpawned || (!(boss == null) && !boss.fsm.currentStateName.Contains("Dead")))
		{
			return;
		}
		int num = 0;
		int num2 = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			num2++;
			if (player.fsm.currentStateName.Contains("Dead"))
			{
				num++;
			}
		}
		if (!bossDefeated && num != num2)
		{
			if (finalBoss != null)
			{
				if (finalBoss.chaosMode)
				{
					if (!secondFormStarted)
					{
						secondFormStarted = true;
						StartCoroutine(ChaosIntro());
					}
					return;
				}
				if (superModeAvailable && !finalBoss.superMode)
				{
					if (!thirdFormStarted)
					{
						thirdFormStarted = true;
						StartCoroutine(SuperIntro());
					}
					return;
				}
			}
			bossDefeated = true;
			GameController.stageTitleUI.AnnounceVictory();
			StartCoroutine(BossOutro());
		}
		else if (bossDespawned && !HandlePvP() && !exitSpawned)
		{
			exitSpawned = true;
			StartCoroutine(ActivateExitPortal());
		}
	}
	public IEnumerator ChaosIntro()
	{
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		if (playBossDialog)
		{
			GameController.PauseAllPlayers();
			while (!GameUI.dialogManager.HandleDialog(bossChaosIntroDialogID, resetOnExit: true, unpauseOnComplete: false, 0.25f))
			{
				yield return null;
			}
		}
		boss.fsm.ChangeState("Intro");
		yield return new WaitForSeconds(3.15f);
		if (playBossDialog)
		{
			GameController.PauseAllPlayers(state: false);
		}
		boss.fsm.ChangeState(boss.fsm.defaultStateName);
		boss.health.invulnerable = false;
		boss.health.showDamageNumbers = true;
		bossSpawned = true;
	}
	public IEnumerator SuperIntro()
	{
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		LootManager.DropPlat(boss.transform.position, 25);
		if (playBossDialog)
		{
			GameController.PauseAllPlayers();
			while (!GameUI.dialogManager.HandleDialog(bossSuperIntroDialogID, resetOnExit: true, unpauseOnComplete: false, 0.25f))
			{
				yield return null;
			}
		}
		bool restoreHP = Inventory.EitherPlayerHasItem(OneHPOneDamage.staticID);
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && !(player.health == null))
			{
				player.health.evadeStat.Modify(devadeMod, addMod: true);
				player.inventory.RemoveItem(OneHPOneDamage.staticID, forceOverride: true, showNotice: true);
				player.inventory.RemoveItem(FlatDamage.staticID, forceOverride: true, showNotice: true);
				if (restoreHP)
				{
					player.health.RestoreHealth(999, showDisplayText: true, playSound: true, fullyRestoreHealth: true);
				}
			}
		}
		boss.fsm.ChangeState("Intro");
		yield return new WaitForSeconds(3f);
		if (playBossDialog)
		{
			GameController.PauseAllPlayers(state: false);
		}
		boss.fsm.ChangeState(boss.fsm.defaultStateName);
		boss.health.showDamageNumbers = true;
		bossSpawned = true;
	}
	public IEnumerator SummonArena()
	{
		boss.anim.Play("GroundSlamDownHoodless", -1, 0f);
		yield return Globals.waitForQuarter;
		CameraController.ShakeCamera();
		SoundManager.PlayBGM("FinalBoss");
		SoundManager.PlayAudio("ChaosLightningCrackle");
		SoundManager.PlayAudio("ChaosFormLong");
		IEnumerator enumerator = GameObject.Find("FinalBossArena").transform.GetEnumerator();
		try
		{
			while (enumerator.MoveNext())
			{
				Transform transform = (Transform)enumerator.Current;
				transform.gameObject.SetActive(value: true);
			}
		}
		finally
		{
			IDisposable disposable2;
			IDisposable disposable = (disposable2 = enumerator as IDisposable);
			if (disposable2 != null)
			{
				disposable.Dispose();
			}
		}
		GameObject.Find("FinalBossStageObjects").SetActive(value: false);
		SpriteRenderer throneRenderer = GameObject.Find("FinalBossWalkup").GetComponentInChildren<SpriteRenderer>();
		SpriteRenderer throneOverlayRenderer = throneRenderer.transform.Find("FinalBossWalkupOverlay").GetComponentInChildren<SpriteRenderer>();
		Material throneMat = throneRenderer.material;
		throneOverlayRenderer.enabled = false;
		float dissolveAmount = 0f;
		throneMat.SetFloat("_FlashAmount", 1f);
		if (!playBossDialog)
		{
			Vector3 vector = Vector3.right * 4f;
			Vector3 vector2 = bossSpawnPosition + Vector3.down * 4f - vector * (GameController.activePlayers.Length - 1);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (!(player == null))
				{
					player.TeleportToArea(vector2, showSpawnPortal: true, randomize: false);
					vector2 += vector * 2f;
				}
			}
		}
		yield return waitForSplitSec;
		stageLight.intensity = 0.4f;
		lightContainer.SetActive(value: false);
		while (dissolveAmount < 1f)
		{
			dissolveAmount += 0.025f;
			throneMat.SetFloat("_DissolveAmount", dissolveAmount);
			throneMat.SetFloat("_FlashAmount", Mathf.Clamp(1f - dissolveAmount * 4f, 0f, 1f));
			yield return waitForSplitSec;
		}
		throneMat.SetFloat("_DissolveAmount", 1f);
		throneMat.SetFloat("_FlashAmount", 0f);
		boss.anim.Play("StandUpHoodless", -1, 0f);
	}
	public override IEnumerator BossIntro()
	{
		ChaosBundle.LoadBGM("FinalBoss");
		CameraController camController = GameController.cameraController;
		Vector3 originalCameraPosition = ((!(cameraLockPosition == Vector3.zero)) ? cameraLockPosition : camController.transform.position);
		bool horiOnly = ((!overrideCameraLocks) ? camController.HoriMoveOnly : (!overrideHoriLockValue));
		bool vertOnly = ((!overrideCameraLocks) ? camController.VertMoveOnly : (!overrideVertLockValue));
		int torchCount = 14;
		Torch[] torches = new Torch[torchCount];
		Torch[] finalTorches = new Torch[4];
		GameObject lightsObj = GameObject.Find("Lights");
		finalTorches[0] = lightsObj.transform.Find("TorchCornerL").GetComponent<Torch>();
		finalTorches[1] = lightsObj.transform.Find("TorchCornerR").GetComponent<Torch>();
		finalTorches[2] = lightsObj.transform.Find("WallTorchL").GetComponent<Torch>();
		finalTorches[3] = lightsObj.transform.Find("WallTorchR").GetComponent<Torch>();
		for (int i = 0; i < torchCount; i += 2)
		{
			torches[i] = lightsObj.transform.Find("TorchRow" + i / 2 + "L").GetComponent<Torch>();
			torches[i + 1] = lightsObj.transform.Find("TorchRow" + i / 2 + "R").GetComponent<Torch>();
		}
		if (!Level.isBossRushMode)
		{
			if (!superModeAvailable)
			{
				bool flag = false;
				for (int j = 0; j < superModeLamps.Length; j++)
				{
					if (superModeLamps[j] != null)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					superModeAvailable = true;
				}
			}
			if (superModeAvailable)
			{
				SoundManager.PlayAudio("WindHowl", 1f, ignoreTimeRestriction: false, 0.5f);
