	private void UpdateHairPosition()
	{
		hairEffectTrans.position = hairSpriteTrans.position + hairEffectYOffset;
		hairSideEffectTrans.position = hairSpriteTrans.position + hairEffectYOffset;
		hairEffectSorter0.yValueOffset = 0f;
		hairEffectSorter1.yValueOffset = 0f;
		int num = (int)hairOffsetMode;
		if (hairOffsetMode == 0f || hairOffsetMode == 2f)
		{
			if (hairOffsetMode == 0f)
			{
				hairEffectSorter0.yValueOffset = -1.75f;
				hairEffectSorter1.yValueOffset = -1.75f;
			}
			hairEffectObj.SetActive(value: true);
			hairSideEffectObj.SetActive(value: false);
			return;
		}
		switch (num)
		{
		case 1:
			hairSideEffectTrans.position = hairSpriteTrans.position + hairSideEffectYOffset - hairEffectXOffset * transform.localScale.x;
			hairSideEffectTrans.transform.localEulerAngles = hairSideEffectRotation;
			break;
		case 3:
			hairSideEffectTrans.position = hairSpriteTrans.position + hairSideEffectYOffset + hairEffectXOffset * transform.localScale.x;
			hairSideEffectTrans.transform.localEulerAngles = -hairSideEffectRotation;
			break;
		}
		hairSideEffectObj.SetActive(value: true);
		hairEffectObj.SetActive(value: false);
	}
