	public virtual void PlayWaterFormEffect()
	{
		for (int i = 0; i < 2; i++)
		{
			Transform transform = parent.rightHandTrans;
			if (i == 0)
			{
				transform = parent.leftHandTrans;
				if (parent.facingDirection == FacingDirection.Left || parent.facingDirection == FacingDirection.Right)
				{
					continue;
				}
			}
			waterFormEffects[i].followTransform = transform;
			waterFormEffects[i].Play(56f, null, null, 0.2f);
			waterBounceProjs[i] = Globals.ChaosInst<WaterBounceProjectile>(WaterBounceProjectile.Prefab, parent.bossObjects, transform.position);
			waterBounceProjs[i].DisableAllColliders();
			waterBounceProjs[i].enabled = false;
			waterBounceProjs[i].moveSpeed = 0f;
			waterBounceProjs[i].flyTime = 0.4f;
			waterBounceProjs[i].gameObject.GetComponent<AnimationRandomizer>().enabled = false;
			poolItem.followTransform = transform;
			poolItem.Emit(1);
