	public override void ExecuteSkill()
	{
		if (!beamsCreated)
		{
			beamsCreated = true;
			delayStopwatch.IsRunning = true;
			atkTransPos = parent.attackOriginTrans.position;
			spawnPos = atkTransPos + spawnRange * targetVector;
			leftBeam = CreateAquaBeam(spawnPos, targetVector);
			rightBeam = CreateAquaBeam(spawnPos, targetVector);
			lerpVector = Globals.GetPerpendicular(targetVector);
			leftEndVector = (lerpVector - targetVector * overShootValue).normalized;
			rightEndVector = (-lerpVector - targetVector * overShootValue).normalized;
			CameraController.ShakeCamera();
			StopWaterFormEffect();
			UpdateArmAngles(parent.closestTargetInfo.position, parent.closestTargetInfo.position);
		}
		else if (lerpComplete)
		{
			base.ExecuteSkill();
		}
	}
	public void UpdateArmAngles(Vector2 leftTargetVec, Vector2 rightTargetVec)
	{
		if (!(rightBeam == null) && !(leftBeam == null) && (parent is IceBoss || parent is FinalBoss))
		{
			Vector3 vector = rightBeam.transform.TransformPoint(rightBeam.transform.localPosition + Vector3.up * overShootValue);
			Vector3 vector2 = leftBeam.transform.TransformPoint(leftBeam.transform.localPosition + Vector3.up * overShootValue);
			parent.rightArmTrans.transform.localEulerAngles = Globals.GetRotationVector((((!parent.isFacingRight) ? vector2 : vector) - parent.rightArmTrans.position).normalized) * ((!parent.isFacingRight) ? (-1f) : 1f);
			parent.leftArmTrans.transform.localEulerAngles = Globals.GetRotationVector((((!parent.isFacingRight) ? vector : vector2) - parent.leftArmTrans.position).normalized) * ((!parent.isFacingRight) ? (-1f) : 1f);
		}
	}
	public override void FixedUpdate()
