		if (beamsCreated && !delayStopwatch.IsRunning && !lerpComplete)
		{
			if (!lerpStarted)
			{
				lerpStarted = true;
				lerpStopwatch.IsRunning = true;
			}
			lerpComplete = lerpValue >= 1f;
			lerpValue = lerpStopwatch.TimePercentage;
			if (lerpComplete)
			{
				leftBeam.StopBeam();
				rightBeam.StopBeam();
				return;
			}
			Vector2 leftTargetVec = Vector2.Lerp(targetVector, leftEndVector, lerpValue);
			lerpVector = leftTargetVec.normalized;
			leftBeam.transform.position = atkTransPos + lerpVector * spawnRange;
			leftBeam.transform.localEulerAngles = Globals.GetRotationVector(lerpVector);
			Vector2 rightTargetVec = Vector2.Lerp(targetVector, rightEndVector, lerpValue);
			lerpVector = rightTargetVec.normalized;
			rightBeam.transform.position = atkTransPos + lerpVector * spawnRange;
			rightBeam.transform.localEulerAngles = Globals.GetRotationVector(lerpVector);
			UpdateArmAngles(leftTargetVec, rightTargetVec);
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		StopWaterFormEffect();
	}
