	{
		if (!iceWaveSpawned)
		{
			iceWaveSpawned = true;
			CreateAllIceWaves();
			return;
		}
		iceWaveDone = mainIW == null || !mainIW.IsSpawning;
		if (!iceWaveDone)
		{
			containerTrans.position = mainIW.activationPosition;
			movementVector = mainIW.moveVector;
			containerTrans.localEulerAngles = Globals.GetRotationVector(movementVector);
			if (!followWave)
			{
				return;
			}
			followWave = (float)mainIW.wavesElapsed < 0.75f * (float)waveCount;
			mainIW.homing = followWave;
			if (followWave)
			{
				return;
			}
			mainIW.moveVector = (movementVector + UpdateTargetVector(updateInfo: false, useTransform: true)).normalized;
			{
				foreach (IceWaveBase iw in iwList)
				{
					if (iw != null)
					{
						iw.spawnWaveThroughStopLayermask = false;
					}
				}
				return;
			}
		}
		if (mainIW != null)
		{
			IceWaveBase iceWaveBase = mainIW;
		}
		parent.iceWheelAnim.Play("Open", -1, 0f);
		base.ExecuteSkill();
	}
	public override void FixedUpdate()
	{
		if (iceWaveSpawned && !iceWaveDone && followWave)
		{
			parent.rigidbody2D.MovePosition(Vector2.Lerp(parent.transform.position, containerTrans.position, activateStopwatch.TimePercentage));
		}
