		}
		containerTrans = new GameObject("IceWaveContainer").transform;
		containerTrans.SetParent(parent.bossObjects);
		for (int i = 0; i < spawnCount; i++)
		{
			Transform transform = new GameObject().transform;
			transform.SetParent(containerTrans);
			followTransList.Add(transform);
			switch (i)
			{
			case 0:
				transform.localPosition = new Vector2(0f, 1f);
				break;
			case 1:
				transform.localPosition = new Vector2(-1f, 0.5f);
				break;
			case 2:
				transform.localPosition = new Vector2(1f, 0.5f);
				break;
			case 3:
				transform.localPosition = new Vector2(-2f, -1f);
				break;
			case 4:
				transform.localPosition = new Vector2(2f, -1f);
				break;
			}
		}
	}
	private void CreateAllIceWaves()
	{
		containerTrans.position = parent.transform.position;
		containerTrans.localEulerAngles = Globals.GetRotationVector(UpdateTargetVector(updateInfo: true));
		iwList.Clear();
		mainIW = CreateIceWave(targetTransform, setAsSpawn: false);
		IceWaveBase iceWaveBase = mainIW;
		IceWaveBase iceWaveBase2 = mainIW;
		activateStopwatch.SetDelay(mainIW.spawnRate);
		for (int i = 0; i < spawnCount; i++)
		{
			CreateIceWave(followTransList[i], setAsSpawn: true);
		}
	}
	private IceWaveBase CreateIceWave(Transform givenTrans, bool setAsSpawn)
	{
		currentIW = ChaosInst<IceWaveBase>(IceWaveBase.Prefab);
		if (setAsSpawn)
		{
			currentIW.spawnTransform = givenTrans;
			currentIW.disableLights = true;
			iwList.Add(currentIW);
		}
		else
		{
			currentIW.homing = true;
			currentIW.homingBias = 7;
			currentIW.targetTrans = givenTrans;
		}
		currentIW.SetSkillData(parent.skillCategory, skillID);
		currentIW.spawnRate = Mathf.Lerp(0.09f, 0.07f, currentDiffValue);
		currentIW.wavePoolSize = 10;
		currentIW.maxWaveCount = waveCount;
		currentIW.ignoreWaveCollisions = true;
		currentIW.spawnWaveThroughStopLayermask = true;
		currentIW.spawnReturnWave = false;
		return currentIW;
	}
}
