			fistPumpPlayed = false;
			fistPumpDelayDone = false;
			parent.anim.Play("Outro", -1, 0f);
			parent.Partner.MoveAndAnimate(parent.transform.position + Vector3.right, "FistPump", givenHoldAnim: false, 0f, skipAfterImage: true, skipLanding: true, skipLandingStrike: true);
		}
		public override void Update()
		{
			if (destroyQueued)
			{
				return;
			}
			if (!frameSkipped)
			{
				frameSkipped = true;
				return;
			}
			if (!fistPumpPlayed)
			{
				if (!parent.anim.AnimPlayed())
				{
					parent.Partner.PlayAnim("FistPump");
					return;
				}
				parent.Partner.PlayAnim("FistPump", 1f);
				fistPumpPlayed = true;
				CameraController.ShakeCamera(0.3f);
				return;
			}
			if (!fistPumpDelayDone)
			{
				if (!parent.anim.AnimPlayed(1.15f))
				{
					return;
				}
				fistPumpDelayDone = true;
			}
			parent.anim.Play("Hidden");
			parent.Partner.SpawnTeleportEffect(parent.Partner.transform.position, isLanding: true);
			parent.Partner.PlayAnim("Hidden");
			EmitStatueMetalBreak(parent.transform.position);
			if (parent.Partner.gameObject != null)
			{
				UnityEngine.Object.Destroy(parent.Partner.gameObject, 1f);
			}
			if (parent.gameObject != null)
			{
				UnityEngine.Object.Destroy(parent.gameObject, 1f);
			}
			destroyQueued = true;
		}
	}
