public class LightningBossShockNetState : BossSkillState
{
	private ParticleSystemOverride lfOverride = new ParticleSystemOverride
	{
		radius = 5f
	};

	private ChaosQuickStopwatch landStopwatch = new ChaosQuickStopwatch(0.25f);
	private List<MetalOrb> moList = new List<MetalOrb>();
	private MetalOrb currentMO;
	public new LightningBoss parent;
	public LightningBossShockNetState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		slamPlayed = false;
		standPlayed = false;
		crossArmPlayed = false;
		windupTime = StdWindupTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 3f;
		spawnPosition = parent.GetTrackingPosition();
		parent.SetColliderStatus(givenStatus: true, partnerStatus: false);
		CameraController.ShakeCamera(0.25f);
		poolItem.Emit(2, spawnPosition);
		poolItem.Emit(1, spawnPosition + Vector2.up, null, null, 0.1f);
		poolItem.Emit(1, spawnPosition + Vector2.up * 1.5f, null, null, 0.2f);
		landStarted = false;
		landCompleted = false;
	}
	public override void Update()
	{
		base.Update();
		if (!standPlayed && exitQueued && ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.25f)
		{
			standPlayed = true;
		}
		{
			crossArmPlayed = true;
		}
	}
	public override void ExecuteSkill()
	{
		if (!slamPlayed)
		{
			slamPlayed = true;
			CreateAllOrbs();
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			return;
		}
		if (!landCompleted)
		{
			if (!landStarted)
			{
				landStarted = true;
				landStopwatch.IsRunning = true;
				parent.Partner.QueueMode("Land", spawnPosition, 1, skillID, 2);
				parent.Partner.lightningAuraEmitter.Play(14f, parent.Partner.transform.position + Vector3.up);
				parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			}
			if (landStopwatch.IsRunning)
			{
				return;
			}
			landCompleted = true;
		}
		base.ExecuteSkill();
		for (int num = moList.Count - 1; num >= 0; num--)
		{
			if (moList[num] != null)
			{
				moList[num].ActivateNet();
			}
		}
		moList.Clear();
		if (!slamPlayed)
		{
			slamPlayed = true;
		}
		parent.Partner.lightningAuraEmitter.Play(20f, parent.Partner.transform.position + Vector3.up);
	}
	public override void OnExit()
	{
		base.OnExit();
		for (int num = moList.Count - 1; num >= 0; num--)
		{
			if (moList[num] != null)
			{
				moList[num].Reset();
			}
		}
		moList.Clear();
		parent.Partner.lightningAuraEmitter.Stop();
		parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
	}
	private void CreateAllOrbs()
	{
		int particleCount = 40;
		float scale = 0.5f;
		Vector3? emitPosition = parent.transform.position;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		CameraController.ShakeCamera(0.25f);
		targetPosition = spawnPosition + Vector2.up;
		randomSeed = UnityEngine.Random.Range(0, orbCount);
		lfOverride.startLifetime = windupTime;
		for (int i = 0; i < orbCount; i++)
		{
			moList.Add(CreateMetalOrb(GetCalculatedPosition(spawnPosition, i), skillID));
			moList[i].lsList.Add(targetPosition);
			moList[i].lsList.Add(GetCalculatedPosition(targetPosition, (i + 3) % orbCount));
			moList[i].lsList.Add(GetCalculatedPosition(targetPosition, (i + 1) % orbCount));
		}
	}
	private MetalOrb CreateMetalOrb(Vector2 givenPosition, string givenID, int givenCount = 5)
	{
		currentMO = Globals.ChaosInst<MetalOrb>(MetalOrb.Prefab, parent.bossObjects, givenPosition);
		currentMO.SetSkillInfo(parent.skillCategory, givenID);
		currentMO.hitCount = givenCount;
		return currentMO;
	}
	private Vector2 GetCalculatedPosition(Vector2 givenPosition, int givenIndex)
	{
		return givenPosition + 5f * Globals.GetCirclePositionVector(orbCount * 5, givenIndex * 5 + randomSeed);
	}
}
public class LightningBossShockBlenderState : BossSkillState
{
	private List<OrbMetalFamiliar> orbList = new List<OrbMetalFamiliar>();
	private OrbMetalFamiliar currentOF;
	private NumVarStatMod healthMod;
	public new LightningBoss parent;
	public LightningBossShockBlenderState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		healthMod = new NumVarStatMod(newName, 25f, 10, VarStatModType.Override, fillToNewMax: true);
	}
	public override void OnEnter()
	{
		if (!parent.DashToPosition(name, BlenderGuyPos))
		{
			dashToPosCompleted = true;
			base.OnEnter();
			parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			parent.Partner.MoveAndAnimate(BlenderGirlPos, "FistPump", givenHoldAnim: true);
			orbsSpawned = false;
			standPlayed = false;
			crossArmPlayed = false;
			windupTime = StdWindupTime * 0.75f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 3f;
			CleanOrbList();
			if (orbList.Count > 0)
			{
				BurstAllOrbs(givenStatus: true, windupTime * 2f);
			}
		}
	}
	public override void WindupUpdate()
	{
		if (!orbsSpawned)
		{
		}
	}
	public override void Update()
	{
		base.Update();
		if (!exitQueued)
		{
			return;
		}
		if (!standPlayed)
		{
			if (ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.3f)
			{
				standPlayed = true;
			}
		}
		else if (!crossArmPlayed && ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.6f)
		{
			crossArmPlayed = true;
		}
	}
	public override void ExecuteSkill()
	{
		if (!orbsSpawned)
		{
			orbsSpawned = true;
			SummonAllOrbs();
			int particleCount = 40;
			float scale = 0.5f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			CameraController.ShakeCamera(0.25f);
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		}
		else
		{
			base.ExecuteSkill();
			BurstAllOrbs(givenStatus: false, 0f, emitHitEffect: true);
		}
	}
	public override void OnExit()
	{
		if (dashToPosCompleted)
		{
			dashToPosCompleted = false;
			base.OnExit();
		}
	}
	private void SummonAllOrbs()
	{
		currentPosition = parent.transform.position;
		for (int i = 0; i < spawnCount; i++)
		{
			SummonMetalOrb(currentPosition + spawnRange * Globals.GetCirclePositionVector(spawnCount, i));
		}
	}
	private void SummonMetalOrb(Vector2 givenPosition)
	{
		currentOF = (OrbMetalFamiliar)Enemy.Spawn("OrbMetalFamiliar", givenPosition, parent.transform.parent, dropLoot: false, alerted: true, spawnCard: false, survivalMode: false, overrideCountDeath: true);
		currentOF.parentSummoner = parent.gameObject;
		currentOF.summoned = true;
		currentOF.health.healthStat.AddMod(healthMod);
		currentOF.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentOF.skillCategory = parent.skillCategory;
		currentOF.attackSkillID = skillID;
		orbList.Add(currentOF);
	}
	private void CleanOrbList()
	{
		for (int num = orbList.Count - 1; num >= 0; num--)
		{
			if (orbList[num] == null)
			{
				orbList.RemoveAt(num);
			}
		}
	}
	private void BurstAllOrbs(bool givenStatus, float burstDelay = 0f, bool emitHitEffect = false)
	{
		for (int num = orbList.Count - 1; num >= 0; num--)
		{
			if (orbList[num] != null)
			{
				orbList[num].QueueBurst(2.5f, burstDelay, givenStatus, emitHitEffect);
			}
			if (givenStatus)
			{
				orbList.RemoveAt(num);
			}
		}
	}
	public void ResetAllMinions()
	{
		foreach (OrbMetalFamiliar orb in orbList)
		{
			if (!(orb == null))
			{
				orb.health.healthStat.CurrentValue = -1f;
				orb.fsm.ChangeState("Dead");
			}

			}
		}
