public class LightningBossSkyJavelinState : BossSkillState
{
	private GameObject targetPrefab = ChaosBundle.Get("Assets/Prefabs/Environment/MetalFloorTarget.prefab");
	private ThunderJavelin currentTJ;
	private List<ShockBurstOrb> orbList;
	public new LightningBoss parent;
	public LightningBossSkyJavelinState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		orbList = new List<ShockBurstOrb>();
	}
	public override void OnEnter()
	{
		base.OnEnter();
		parent.SetColliderStatus(givenStatus: true, partnerStatus: false);
		windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.25f);
		exitTime = StdExitTime * 1.75f;
		parent.Partner.MoveAndAnimate(parent.transform.position + Vector3.up, "Jump", givenHoldAnim: false, 0f, skipAfterImage: false, skipLanding: false, skipLandingStrike: true);
		atkInterval = Mathf.Lerp(0.35f, 0.25f, currentDiffValue);
		atkStarted = false;
		orbsSpawned = false;
		curOrbIndex = 0;
		windupPlayed = false;
		throwStarted = false;
		SpawnOrbs();
	}
	public override void ExecuteSkill()
	{
		if (!atkStarted)
		{
			atkStarted = true;
			atkStopwatchID = ChaosStopwatch.Begin(atkInterval, useInterval: true, atkInterval, atkCount + 1);
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Ready:
			windupPlayed = false;
			if (!throwStarted)
			{
				ThrowOrb();
			}
			throwStarted = false;
			if (curOrbIndex > 0)
			{
				CreateThunderJavelin(parent.Partner.transform.position, (curOrbIndex < atkCount) ? prevTargetPos : curTargetPos);
				parent.Partner.floatState.PlayThrow();
			}
			if (curOrbIndex < atkCount)
			{
				curOrbIndex++;
			}
			if (curOrbIndex < atkCount)
			{
				orbStartPos = orbList[curOrbIndex].transform.position;
			}
			return;
		case StopwatchState.Done:
			parent.Partner.floatState.lastJavelinThrown = true;
			base.ExecuteSkill();
			return;
		}
		atkTimePercent = ChaosStopwatch.GetTimePercentage(atkStopwatchID);
		if (atkTimePercent < 0.5f)
		{
			if (curOrbIndex < atkCount)
			{
				orbList[curOrbIndex].transform.position = Vector3.Lerp(orbStartPos, parent.leftArmTrans.position - Vector3.up * 0.625f, Globals.LerpWithRange(0f, 0.33f, atkTimePercent));
				if (!windupPlayed)
				{
					windupPlayed = true;
				}
			}
		}
		else if (!throwStarted)
		{
			ThrowOrb();
		}
	}
	private void ThrowOrb()
	{
		if (curOrbIndex >= atkCount)
		{
			if (prevTargetPos != curTargetPos)
			{
				prevTargetPos = curTargetPos;
				parent.Partner.floatState.nextTargetPos = curTargetPos;
				parent.Partner.QueueMode("Float", GetMovePosition(prevTargetPos), -1, string.Empty);
			}
			throwStarted = true;
		}
		else if (!(orbList[curOrbIndex] == null))
		{
			orbList[curOrbIndex].transform.position = parent.leftArmTrans.position - Vector3.up * 0.625f;
			UpdateTargetPosition();
			orbList[curOrbIndex].throwPosition = curTargetPos;
			orbList[curOrbIndex].FrisbeeThrow();
			if (curOrbIndex > 0)
			{
				parent.Partner.floatState.nextTargetPos = curTargetPos;
				parent.Partner.QueueMode("Float", GetMovePosition(prevTargetPos), -1, string.Empty);
			}
			throwStarted = true;
		}
	}
	private void SpawnOrbs()
	{
		if (!orbsSpawned)
		{
			orbList.Clear();
			for (int i = 0; i < atkCount; i++)
			{
				orbList.Add(parent.GetBossPoolItem<ShockBurstOrb>());
				orbList[i].transform.position = parent.transform.position + (Vector3)Globals.GetRotatedCircleVector(atkCount, i, Vector3.down) * 1.325f;
				orbList[i].Init(string.Empty, string.Empty, 0, parent.transform.position, atkInterval * 0.5f, ShockBurstOrbMode.Frisbee);
			}
			orbStartPos = orbList[0].transform.position;
			orbsSpawned = true;
		}
	}
	private void UpdateTargetPosition()
	{
		prevTargetPos = curTargetPos;
		curTargetPos = parent.GetTrackingPosition() + UnityEngine.Random.insideUnitCircle;
	}
	private void CreateThunderJavelin(Vector2 givenStart, Vector2 givenEnd)
	{
		currentTJ = ChaosInst<ThunderJavelin>(ThunderJavelin.Prefab, givenStart);
		currentTJ.InitJavelin(parent.skillCategory, skillID, 1, givenUlt: false, 4.75f, 0f, givenEnd);
		if (curOrbIndex <= atkCount && curOrbIndex > 0)
		{
			ThunderJavelin thunderJavelin = currentTJ;
		}
	}
	private void CreateMetalTarget(Vector2 givenPosition)
	{
		UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(targetPrefab, givenPosition, Quaternion.identity), atkInterval + 0.125f);
	}
	private Vector2 GetMovePosition(Vector2 givenPosition)
	{
		return givenPosition + new Vector2(UnityEngine.Random.Range(-2f, 2f), UnityEngine.Random.Range(0f, 2f));
	}
}
public class LightningBossDashState : BossSkillState
{
	private ChaosQuickStopwatch dashTimer;
	public new LightningBoss parent;
	public LightningBossDashState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		dashTimer = new ChaosQuickStopwatch();
	}
	public override void OnEnter()
	{
		frameSkipped = false;
		dashStartAnimDone = false;
		dashEndAnimDone = false;
		moveDone = false;
		startPos = parent.transform.position;
		Vector3? vector = targetPosOverride;
		Vector3 vector2;
		if (!vector.HasValue)
		{
			vector2 = parent.stageCenter;
		}
		else
		{
			Vector3? vector3 = targetPosOverride;
			vector2 = vector3.Value;
		}
		targetPos = vector2;
	}
	public override void Update()
	{
		if (!frameSkipped)
		{
			frameSkipped = true;
		}
		else if (!dashStartAnimDone)
		{
			{
				if (dashTime > 0f)
				{
					dashTimer.SetDelay(dashTime);
					dashTimer.IsRunning = true;
				}
				dashStartAnimDone = true;
			}
		}
		else if (!moveDone)
		{
			if (!dashTimer.IsRunning)
			{
				parent.transform.position = targetPos;
				moveDone = true;
			}
		}
		{
			EmitStatueMetalBreak(parent.transform.position);
			dashEndAnimDone = true;
			parent.fsm.ChangeState(queuedStateName);
		}
	}
	public override void FixedUpdate()
	{
		if (dashTimer.IsRunning)
		{
			parent.transform.position = Vector3.Lerp(startPos, targetPos, dashTimer.TimePercentage);
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		targetPosOverride = null;
	}
}
public class LightningBossThunderDrumState : BossSkillState
{
	private ThunderWave currentTW;
	public new LightningBoss parent;
	public LightningBossThunderDrumState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}
	public override void OnEnter()
	{
		if (!parent.DashToPosition(name, DrumGuyPos))
		{
			dashToPosCompleted = true;
			base.OnEnter();
			parent.SetColliderStatus(givenStatus: false, partnerStatus: true);
			parent.FaceTarget(parent.transform.position + Vector3.right);
			parent.Partner.QueueMode("Drum", parent.Partner.transform.position, -1, string.Empty);
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime * 1.5f);
			exitTime = StdExitTime * 2f;
			atkStarted = false;
			windupPlayed = false;
		}
	}
	public override void ExecuteSkill()
	{
		if (!atkStarted)
		{
			atkStarted = true;
			atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, windupTime, atkCount);
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Ready:
			windupPlayed = false;
			frameSkipped = false;
			waitForHitAnim = true;
			isRight = !isRight;
			parent.Partner.drumState.HitDrum(isRight, isWindup: false);
			currentPosition = parent.transform.position + ((!isRight) ? Vector3.left : Vector3.right) * 1.5f;
			if (parent.UpdateTargetInfo() != null)
			{
				targetVector = ((Vector2)parent.closestTargetInfo.position - currentPosition).normalized;
				CreateThunderWave(currentPosition, targetVector);
			}
			break;
		case StopwatchState.Done:
			{
				parent.Partner.drumState.EndDrum();
				base.ExecuteSkill();
			}
			break;
		case StopwatchState.Running:
			if (!frameSkipped)
			{
				frameSkipped = true;
			}
			else if (!windupPlayed && (!waitForHitAnim || parent.Partner.AnimPlayed(0.8f)))
			{
				parent.Partner.drumState.HitDrum(!isRight);
				windupPlayed = true;
				waitForHitAnim = false;
			}
			break;
		}
	}
	public override void OnExit()
	{
		if (dashToPosCompleted)
		{
			dashToPosCompleted = false;
			base.OnExit();
			parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
		}
	}
	private void CreateThunderWave(Vector2 givenPosition, Vector2 givenVector)
	{
		currentTW = ChaosInst<ThunderWave>(ThunderWave.Prefab, givenPosition);
		currentTW.SetSkillData(parent.skillCategory, skillID);
		currentTW.moveVector = givenVector;
		currentTW.maxWaveCount = 16;
		currentTW.wavePoolSize = 16;
		currentTW.burstScale = 2f;
		currentTW.spacing = 1.75f;
		currentTW.spawnRate = windupTime * 0.25f;
	}
}
public class LightningBossChainSpinState : BossSkillState
{
	private LightningChain currentLC;
	private ChaosQuickStopwatch effectTimer = new ChaosQuickStopwatch(0.08f);
	public new LightningBoss parent;
	public LightningBossChainSpinState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}
	public override void OnEnter()
	{
		if (!parent.DashToPosition(name, parent.stageCenter))
		{
			dashToPosCompleted = true;
			pullPlayed = false;
			frameSkipped = true;
			isFirstDash = true;

				isFirstDash = true;
				isSecondDash = true;
				base.OnEnter();
				parent.SetColliderStatus(givenStatus: false, partnerStatus: true);
				parent.Partner.MoveAndAnimate(ChainGirlPos);
				parent.Partner.ResetScale();
				windupTime = StdWindupTime * 1.375f;
				windupStopwatchID = ChaosStopwatch.Begin(windupTime);
				moveInterval = Mathf.Lerp(0.5f, 0.375f, currentDiffValue);
				parent.Partner.dashStopwatch.SetDelay(moveInterval - 0.05f);
				moveClockwise = Globals.RandBool;
				moveVec = ((!moveClockwise) ? Vector2.right : Vector2.left);
				moveStarted = false;
				moveCompleted = false;
				parent.jumpSpriteSorter.yValueOffset = -2f;
				CameraController.ShakeCamera(0.25f);
			}
		}
		public override void WindupUpdate()
		{
			base.WindupUpdate();
			if (!frameSkipped)
			{
				frameSkipped = true;
			}
			{
				pullPlayed = true;
			}
		}
		public override void Update()
		{
			base.Update();
			if (pullPlayed && moveStarted && !effectTimer.IsRunning && !(currentLC == null))
			{
				effectTimer.IsRunning = true;
				nextPosition = parent.Partner.leftHandTrans.position;
				currentPosition = parent.transform.position;
				if (!(nextPosition.y - 6f > currentPosition.y))
				{
					partnerVec = (nextPosition - currentPosition).normalized;
				}
			}
		}
		public override void ExecuteSkill()
		{
			if (!moveStarted)
			{
				moveStarted = true;
				moveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, moveInterval, moveCount);
				pullPlayed = true;
				CreateLine();
			}
			if (!moveCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(moveStopwatchID))
				{
				case StopwatchState.Ready:
					if (isFirstDash)
					{
						isFirstDash = false;
						parent.Partner.dashState.isPull = true;
					}
					else if (isSecondDash)
					{
						isSecondDash = false;
						EmpowerLine();
						break;
					}
					moveVec = Globals.GetPerpendicular(moveVec, moveClockwise);
					parent.Partner.dashState.startsLeft = !moveClockwise;
					parent.Partner.dashState.showChainHandle = true;
					currentPosition = parent.Partner.transform.position;
					nextPosition = Globals.GetSafeLinecastVector(currentPosition, moveVec, 99f, ChaosCollisions.layerAllWall);
					parent.CreateWarning(currentPosition + Vector2.up, nextPosition + Vector2.up, moveInterval);
					parent.Partner.QueueMode("Dash", nextPosition, 2, skillID);
					break;
				case StopwatchState.Done:
					moveCompleted = true;
					windupStopwatchID = ChaosStopwatch.Begin(moveInterval);
					break;
				}
			}
			else
			{
				base.ExecuteSkill();
				if (currentLC != null)
				{
					currentLC.Reset();
					currentLC = null;
				}
				EmitStatueMetalBreak(parent.transform.position);
				parent.Partner.transform.localScale = Vector3.one;
				CameraController.ShakeCamera(0.2f);
			}
		}
		public override void OnExit()
		{
			if (dashToPosCompleted)
			{
				dashToPosCompleted = false;
				base.OnExit();
				parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
				if (currentLC != null)
				{
					currentLC.Reset();
					currentLC = null;
				}
			}
		}
		private void CreateLine()
		{
			currentLC = ChaosInst<LightningChain>(LightningChain.Prefab, parent.transform.position);
			currentLC.followTrans = parent.transform;
			currentLC.targetTrans = parent.Partner.leftHandTrans;
		}
		private void EmpowerLine()
		{
			if (!(currentLC == null))
			{
				currentLC.attack.SetAttackInfo(parent.skillCategory, skillID);
				currentLC.EmitLineBurst(8);
			}
		}
	}
