	private bool DashToPosition(string queuedStateName, Vector3? targetPos = null, float dashTime = 0.1f)
	{
		if (!fsm.previousStateName.Contains("Dash"))
		{
			if ((targetPos.HasValue && transform.position == targetPos.Value) || (!targetPos.HasValue && transform.position == (Vector3)stageCenter))
			{
				return false;
			}
			dashState.targetPosOverride = targetPos;
			dashState.queuedStateName = queuedStateName;
			dashState.dashTime = dashTime;
			fsm.ChangeState("Dash");
			return true;
		}
		return false;
	}
