	protected Vector2 GetTrackingPosition()
	{
		UpdateTargetInfo();
		if (closestTargetInfo == null || closestTargetInfo.entity == null)
		{
			return Vector2.zero;
		}
		return (Vector2)closestTargetInfo.position + closestTargetInfo.entity.rigidbody2D.velocity.normalized * Mathf.Min(3f, Mathf.Abs(closestTargetInfo.distance - 1f) * 0.3f);
	}
