		skullRenderers = new SpriteRenderer[EnemyCounterBar.maxSkulls];
		skullLights = new Light[EnemyCounterBar.maxSkulls];
		skullEnabledArray = new bool[EnemyCounterBar.maxSkulls];
		for (int i = 0; i < EnemyCounterBar.maxSkulls; i++)
		{
			Transform transform2 = transform.Find("Skull" + i);
			skullRenderers[i] = transform2.Find("Sprite").GetComponent<SpriteRenderer>();
			skullLights[i] = transform2.Find("Light").GetComponent<Light>();
			skullEnabledArray[i] = true;
