	public void SetSkullStates(bool[] skullStates = null, bool enableAll = false, bool disableAll = false)
	{
		if (skullStates == null && !enableAll && !disableAll)
		{
			return;
		}
		for (int i = 0; i < EnemyCounterBar.maxSkulls; i++)
		{
			if (enableAll || skullStates[i])
			{
				skullRenderers[i].sprite = skullSprites[0];
				skullLights[i].enabled = true;
				skullEnabledArray[i] = true;
			}
			else if (disableAll || !skullStates[i])
			{
				skullRenderers[i].sprite = skullSprites[1];
				skullLights[i].enabled = false;
				skullEnabledArray[i] = false;
			}
		}
	}
