	{
		SetSkullStates(null, enableAll: true);
	}
	private IEnumerator FlashSkulls()
	{
		for (int i = 0; i < skullEnabledArray.Length; i++)
		{
			skullRenderers[i].sprite = skullSprites[1];
			skullLights[i].enabled = false;
		}
		yield return new WaitForSeconds(0.5f);
		for (int j = 0; j < skullEnabledArray.Length; j++)
		{
			if (skullEnabledArray[j])
			{
				skullRenderers[j].sprite = skullSprites[0];
				skullLights[j].enabled = true;
				CameraController.ShakeCamera(0.3f);
				yield return new WaitForSeconds(0.2f);
			}
		}
		yield return new WaitForSeconds(0.1f);
		anim.Play("Break", -1, 0f);
		breakAnimStarted = true;
		rockEmitter = PoolManager.GetPoolItem<RockDebrisEmitter>();
		rockEmitter.PlaySingle(RockDebrisType.Dark, 60f, transform.position + Vector3.up, RockDebrisEmitter.FloorExplosionOverride);
		DustEmitter dustEmitter = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 8;
		float startSpeed = 0f;
		float startSize = 4f;
		Vector3? emitPosition = transform.position;
		particleCount = 4;
		startSize = 0f;
		startSpeed = 0f;
		emitPosition = transform.position - Vector3.right;
		particleCount = 4;
		startSpeed = 0f;
		startSize = 3f;
		emitPosition = transform.position + Vector3.right;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		particleCount = 40;
		startSize = 0.01f;
		emitPosition = transform.position;
		poolItem.EmitCircle(particleCount, startSize, -1f, -1f, emitPosition);
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, transform.position + Vector3.up * 1.5f);
		yield return new WaitForSeconds(0.15f);
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(4, transform.position + Vector3.up * 1.5f);
	}
