		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(RockDebrisType.Dark, 10, transform.position + Vector3.up * 4f, RockDebrisEmitter.CircleExplosionOverride);
		PoolManager.GetPoolItem<ParticleEffect>("CursedAuraBurstEffect").Emit(10, transform.position + Vector3.up * 2f, ParticleEffectOverrides.StartColorBlackAlpha0p25);
