public class ShockBox : MonoBehaviour
{
	private static GameObject prefab;
	public Transform[] transArr;
	public SpriteRenderer[] spriteArr;
	public Sprite shockSprite;
	private Vector2 centerPosition = Vector2.zero;
	private Vector2[] cornerArr = new Vector2[4];
	private LightningBoss parentBoss;
	private string skillID = string.Empty;
	private float hitRange = 1f;
	private int hitCount = 1;
	private int moveStopwatchID;
	private float moveTime = 0.35f;
	private float moveLerpValue;
	private bool moveCompleted;
	private int delayStopwatchID;
	private float delayTime = 0.25f;
	private bool delayCompleted;
	private bool destroyQueued;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockBox.prefab"));
	public void Initialize(LightningBoss givenBoss, string givenID, float givenRange, int givenCount, float givenMove, float givenDelay)
	{
		parentBoss = givenBoss;
		skillID = givenID;
		hitRange = givenRange;
		hitCount = givenCount;
		moveTime = givenMove;
		delayTime = givenDelay;
		centerPosition = transform.position;
		ref Vector2 reference = ref cornerArr[0];
		reference = centerPosition + new Vector2(-1f, 1f) * hitRange;
		ref Vector2 reference2 = ref cornerArr[1];
		reference2 = centerPosition + new Vector2(1f, 1f) * hitRange;
		ref Vector2 reference3 = ref cornerArr[2];
		reference3 = centerPosition + new Vector2(1f, -1f) * hitRange;
		ref Vector2 reference4 = ref cornerArr[3];
		reference4 = centerPosition + new Vector2(-1f, -1f) * hitRange;
	}
	private void Start()
	{
		moveStopwatchID = ChaosStopwatch.Begin(moveTime);
	}
	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (!moveCompleted)
		{
			moveLerpValue = Globals.GetSmoothLerpValue(ChaosStopwatch.GetTimePercentage(moveStopwatchID));
			for (int i = 0; i < 4; i++)
			{
				transArr[i].position = Vector2.Lerp(centerPosition, cornerArr[i], moveLerpValue);
			}
			if (!(moveLerpValue >= 1f))
			{
				return;
			}
			moveCompleted = true;
			delayStopwatchID = ChaosStopwatch.Begin(delayTime);
			for (int j = 0; j < 4; j++)
			{
				CreateWarning(cornerArr[j], cornerArr[(j + 1) % 4]);
			}
		}
		if (!delayCompleted)
		{
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			delayCompleted = true;
		}
		for (int k = 0; k < 4; k++)
		{
			CreateStream(cornerArr[k], cornerArr[(k + 1) % 4]);
			spriteArr[k].sprite = shockSprite;
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, transArr[k].position);
			PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(2, transArr[k].position);
		}
		CameraController.ShakeCamera(0.25f);
		destroyQueued = true;
		Object.Destroy(gameObject, (float)hitCount * 0.125f);
	}
	private void CreateStream(Vector2 givenStart, Vector2 givenEnd)
	{
		if (parentBoss != null)
		{
			parentBoss.CreateStream(skillID, givenStart, givenEnd, hitCount, 0.1f, 0.375f);
		}
	}
	private void CreateWarning(Vector2 givenStart, Vector2 givenEnd)
	{
		if (parentBoss != null)
		{
			parentBoss.CreateWarning(givenStart, givenEnd, 0.25f);
		}
	}
	private void OnDestroy()
	{
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter");
		ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter");
		for (int i = 0; i < 4; i++)
		{
			poolItem.Emit(5, transArr[i].position, ParticleEffectOverrides.StartSpeed1);
			poolItem2.Emit(8, transArr[i].position);
		}
	}
}
