public class StunEffect : MonoBehaviour
{
	private const int maxStarCount = 5;
	private const float starUnitRatio = 0.2f;
	private Animator anim;
	private FollowTransform followTransform;
	private SpriteRenderer[] sprites = new SpriteRenderer[5];
	public float duration = 1f;
	public bool playOnStart;
	private bool playing;
	public int stopwatchID;
	public float fullStunOverride;
	public bool useDurationAsFullStun;
	private int disabledStarCount = 5;
	private int activeStarCount;
	private float timeRemaining;
	private float timePercentage;
	private float starRemoveThreshold;
	private AudioSource stunAudio;
	private void Awake()
	{
		anim = GetComponent<Animator>();
		followTransform = GetComponent<FollowTransform>();
		for (int i = 0; i < 5; i++)
		{
			sprites[i] = transform.Find("StarSprite" + i).GetComponent<SpriteRenderer>();
		}
	}
	private void Start()
	{
		if (playOnStart)
		{
			Play();
		}
		else
		{
			Stop();
		}
	}
	private void Update()
	{
		if (!playing)
		{
			return;
		}
		timeRemaining = ChaosStopwatch.GetRemainingTime(stopwatchID);
		if (timeRemaining == 0f)
		{
			Stop();
		}
		if (useDurationAsFullStun)
		{
			timePercentage = ChaosStopwatch.GetTimePercentage(stopwatchID);
		}
		else if (fullStunOverride > 0f)
		{
			if (timeRemaining > fullStunOverride)
			{
				return;
			}
			timePercentage = 1f - timeRemaining / fullStunOverride;
		}
		else
		{
			if (timeRemaining > 1.25f)
			{
				return;
			}
			timePercentage = 1f - timeRemaining / 1.25f;
		}
		starRemoveThreshold = (float)(disabledStarCount + 1) * 0.2f;
		if (activeStarCount > 0 && timePercentage >= starRemoveThreshold)
		{
			sprites[disabledStarCount].enabled = false;
			disabledStarCount++;
			activeStarCount--;
		}
	}
	public void Readjust(float timeRemaining = -1f, int givenStopwatchID = -1)
	{
		if (givenStopwatchID > -1)
		{
			stopwatchID = givenStopwatchID;
		}
		if (timeRemaining == -1f)
		{
			timeRemaining = ChaosStopwatch.GetRemainingTime(stopwatchID);
		}
		else
		{
			ChaosStopwatch.Stop(stopwatchID);
			stopwatchID = ChaosStopwatch.Begin(timeRemaining);
		}
		if (useDurationAsFullStun)
		{
			timePercentage = ChaosStopwatch.GetTimePercentage(stopwatchID);
		}
		else if (fullStunOverride > 0f)
		{
			timePercentage = 1f - Mathf.Clamp(timeRemaining / fullStunOverride, 0f, 1f);
		}
		else
		{
			timePercentage = 1f - Mathf.Clamp(timeRemaining / 1.25f, 0f, 1f);
		}
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = timePercentage < (float)(i + 1) * 0.2f;
		}
	}
	public void Play(int externalStopwatchID = -1, Transform parentTransform = null, Vector3 followOffset = default(Vector3))
	{
		gameObject.SetActive(value: true);
		playing = true;
		activeStarCount = 5;
		disabledStarCount = 0;
		anim.Play("SpinAll");
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = true;
		}
		stopwatchID = externalStopwatchID;
		if (ChaosStopwatch.Check(stopwatchID))
		{
			stopwatchID = ChaosStopwatch.Begin(duration);
		}
		if (parentTransform != null)
		{
			followTransform.followTransform = parentTransform;
			followTransform.followOffset = followOffset;
		}
	}
	public void Stop(bool playRecoveryFX = false)
	{
		playing = false;
		activeStarCount = 0;
		disabledStarCount = 5;
		fullStunOverride = 0f;
		useDurationAsFullStun = false;
		anim.Play("Idle");
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = false;
		}
		ChaosStopwatch.Stop(stopwatchID);
		followTransform.followTransform = null;
		followTransform.followOffset = Vector3.zero;
		if (stunAudio != null)
		{
			stunAudio.Stop();
			stunAudio = null;
		}
		if (playRecoveryFX)
		{
			PoolManager.GetPoolItem<ParticleEffect>("StunRecoverEmote").Emit(1, transform.position);
		}
		gameObject.SetActive(value: false);
	}
}
=========== GenericPool
public class GenericPool<T> where T : class
{
	public static Vector2 initSpawnVec = new Vector2(-200f, 0f);
	private T[] items;
	private int itemIndex;
	private int itemCount;
	public GameObject poolObj;
	public string name;
	public int ItemCount => itemCount;
	public GenericPool(string givenPath, int givenCount = 10, string givenName = "", bool dontDestroyOnLoad = true, Transform givenParent = null)
	{
		InitPool(ChaosBundle.Get(givenPath), givenCount, givenName, dontDestroyOnLoad, givenParent);
	}
	public GenericPool(GameObject givenPrefab, int givenCount = 10, Transform givenParent = null)
	{
		InitPool(givenPrefab, givenCount, string.Empty, givenDestroyOnLoad: false, givenParent);
	}
	private void InitPool(GameObject givenPrefab, int givenCount, string givenName = "", bool givenDestroyOnLoad = true, Transform givenParent = null)
	{
		itemCount = givenCount;
		items = new T[givenCount];
		itemIndex = 0;
		if (givenName == string.Empty)
		{
			givenName = givenPrefab.name + "Pool";
		}
		poolObj = new GameObject(givenName);
		if (givenDestroyOnLoad)
		{
			Object.DontDestroyOnLoad(poolObj);
		}
		poolObj.transform.SetParent(givenParent);
		for (int i = 0; i < itemCount; i++)
		{
			items[i] = Object.Instantiate(givenPrefab, initSpawnVec, givenPrefab.transform.rotation, poolObj.transform).GetComponentInChildren<T>();
		}
	}
	public T GetItem()
	{
		itemIndex++;
		if (itemIndex >= itemCount)
		{
			itemIndex = 0;
		}
		return items[itemIndex];
	}
}

